svg.script:
(()=>{
 const svg=document.currentScript?.ownerSVGElement || document.documentElement;
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const strands=Array.from(svg.querySelectorAll('path'),el=>{const original=el.getAttribute('d'),coords=original.match(/-?[\d.]+/g).map(Number);return {el,original,coords,dirty:false};});
 let target=null,x=0,y=0,power=0,frame=0;
 function schedule(){if(!frame)frame=requestAnimationFrame(draw);}
 function draw(){
  frame=0;
  if(target){x+=(target.x-x)*.26;y+=(target.y-y)*.26;}
  power+=((target?1:0)-power)*.18;
  if(!target&&power<.003)power=0;
  for(const strand of strands){
   const c=strand.coords;
   if(!power){if(strand.dirty){strand.el.setAttribute('d',strand.original);strand.dirty=false;}continue;}
   let changed=false;const out=[];
   for(let k=0;k<c.length;k+=2){let dx=c[k]-x,dy=c[k+1]-y,d=Math.hypot(dx,dy),f=power*Math.max(0,1-d/145)**2;
    if(f)changed=true;
    out.push((c[k]+f*(26+dx*.44)).toFixed(1)+' '+(c[k+1]+f*(dy*.32-10)).toFixed(1));}
   if(changed)strand.el.setAttribute('d','M'+out[0]+' Q'+out.slice(1,-1).join(' ')+' T'+out.at(-1));
   else if(strand.dirty)strand.el.setAttribute('d',strand.original);
   strand.dirty=changed;
  }
  if(target?(Math.hypot(target.x-x,target.y-y)>.1||power<.998):power)schedule();
 }
 window.addEventListener('pointermove',e=>{target=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());if(!power){x=target.x;y=target.y;}schedule();});
 for(const ev of ['pointerleave','pointercancel'])window.addEventListener(ev,()=>{target=null;schedule();});
})();
